when N_Op_Multiply | N_Op_Divide            =>
   declare
      Left           : constant N_Subexpr_Id := Left_Opnd (Expr);
      Right          : constant N_Subexpr_Id := Right_Opnd (Expr);
      L_Type, R_Type : W_Type_Id;
      L_Why, R_Why   : W_Expr_Id;
   begin
      if Has_Fixed_Point_Type (Etype (Left))
        and then Has_Fixed_Point_Type (Etype (Right))
      then
         --  Multiplication/division between fixed-point types
         --  requires the creation of a specific module.

         Create_Fixed_Point_Mult_Div_Theory_If_Needed
           (Typ_Left   => Etype (Left),
            Typ_Right  => Etype (Right),
            Typ_Result => Expr_Type,
            Expr       => Expr);

         L_Type := Base_Why_Type (Etype (Left));
         R_Type := Base_Why_Type (Etype (Right));

      elsif Has_Fixed_Point_Type (Etype (Left)) then
         L_Type := Base_Why_Type (Etype (Left));
         R_Type := EW_Int_Type;

      elsif Nkind (Expr) = N_Op_Multiply
        and then Has_Fixed_Point_Type (Etype (Right))
      then
         L_Type := EW_Int_Type;
         R_Type := Base_Why_Type (Etype (Right));

      else
         L_Type := Base_Why_Type (Left, Right);
         R_Type := Base_Why_Type (Left, Right);
      end if;

      L_Why := Transform_Expr (Left, L_Type, Domain, Local_Params);
      R_Why :=
        Transform_Expr (Right, R_Type, Domain, Local_Params);

      T :=
        New_Binary_Op_Expr
          (Op          => Nkind (Expr),
           Left        => L_Why,
           Right       => R_Why,
           Left_Type   => Etype (Left),
           Right_Type  => Etype (Right),
           Return_Type => Expr_Type,
           Domain      => Domain,
           Ada_Node    => Expr);
   end;

when N_Op_Rem | N_Op_Mod                    =>
   declare
      Left  : constant N_Subexpr_Id := Left_Opnd (Expr);
      Right : constant N_Subexpr_Id := Right_Opnd (Expr);
      Base  : constant W_Type_Id := Base_Why_Type (Left, Right);
      Lty   : constant Type_Kind_Id := Etype (Left);
      Rty   : constant Type_Kind_Id := Etype (Right);
      LT    : constant W_Expr_Id :=
        Transform_Expr (Left, Base, Domain, Local_Params);
      RT    : constant W_Expr_Id :=
        Transform_Expr (Right, Base, Domain, Local_Params);
   begin
      if Is_Hardcoded_Operation (Nkind (Expr), Lty, Rty) then
         T :=
           Transform_Hardcoded_Operation
             (Nkind (Expr),
              Lty,
              Rty,
              Expr_Type,
              LT,
              RT,
              Domain,
              Expr);
      else
         T :=
           New_Binary_Op_Expr
             (Op          => Nkind (Expr),
              Left        => LT,
              Right       => RT,
              Left_Type   => Lty,
              Right_Type  => Rty,
              Return_Type => Expr_Type,
              Domain      => Domain,
              Ada_Node    => Expr);
      end if;
   end;

when N_Op_Divide              =>
   declare
      Oper           : Why_Name_Enum := WNE_Empty;
      Name           : W_Identifier_Id;
      L_Type, R_Type : W_Type_Id;

   begin
      --  Look for the appropriate base scalar type

      if Has_Fixed_Point_Type (Left_Type)
        and then Has_Fixed_Point_Type (Right_Type)
      then
         L_Type := Base_Why_Type (Left_Type);
         R_Type := Base_Why_Type (Right_Type);
         Oper := WNE_Fixed_Point_Div;

         if Has_Fixed_Point_Type (Return_Type) then
            Base := Base_Why_Type (Return_Type);
         else
            pragma Assert (Has_Integer_Type (Return_Type));
            Base := EW_Int_Type;
         end if;

      elsif Has_Fixed_Point_Type (Left_Type) then
         Base := Base_Why_Type (Return_Type);
         L_Type := Base_Why_Type (Left_Type);
         R_Type := EW_Int_Type;
         Oper := WNE_Fixed_Point_Div_Int;
         pragma Assert (L_Type = Base);

      else
         pragma Assert (not Has_Fixed_Point_Type (Return_Type));
         Base := Base_Why_Type (Left_Type, Right_Type);
         L_Type := Base;
         R_Type := Base;
      end if;

      pragma
        Assert
          (if Has_Fixed_Point_Type (Return_Type)
             or else Has_Fixed_Point_Type (Left_Type)
           then Oper /= WNE_Empty);

      --  Construct the operation

      case Oper is
         when WNE_Fixed_Point_Div     =>
            Name :=
              Get_Fixed_Point_Mult_Div_Theory
                (Typ_Left   => Left_Type,
                 Typ_Right  => Right_Type,
                 Typ_Result => Return_Type)
                .Div;

         when WNE_Fixed_Point_Div_Int =>
            Name :=
              Get_Fixed_Point_Theory (Typ => Return_Type).Div_Int;

         when others                  =>
            Name := New_Division (Base);
      end case;

      Left_Rep :=
        Insert_Simple_Conversion
          (Ada_Node => Ada_Node,
           Domain   => Domain,
           Expr     => Left,
           To       => L_Type);
      Right_Rep :=
        Insert_Simple_Conversion
          (Ada_Node => Ada_Node,
           Domain   => Domain,
           Expr     => Right,
           To       => R_Type);

      T :=
        New_Operator_Call
          (Ada_Node   => Ada_Node,
           Domain     => Domain,
           Name       => Name,
           Args       => (1 => Left_Rep, 2 => Right_Rep),
           Reason     => VC_Division_Check,
           Check_Info =>
             New_Check_Info (Divisor => Get_Ada_Node (+Right)),
           Check      =>
             (Domain = EW_Prog
              and then Present (Ada_Node)
              and then Do_Division_Check (Ada_Node)),
           Typ        => Base);

      if Base_Why_Type (Return_Type) /= Base then
         T :=
           Insert_Checked_Conversion
             (Ada_Node => Ada_Node,
              Domain   => Domain,
              Expr     => T,
              To       => Type_Of_Node (Base_Type (Return_Type)));
      end if;
   end;

when N_Op_Rem | N_Op_Mod      =>
   declare
      Base : constant W_Type_Id :=
        Base_Why_Type (Left_Type, Right_Type);
      Name : W_Identifier_Id;

   begin
      Name :=
        (if Why_Type_Is_BitVector (Base)
         then MF_BVs (Base).Urem
         elsif Op = N_Op_Rem
         then M_Int_Div.Rem_Id
         else M_Int_Div.Mod_Id);

      T :=
        New_Operator_Call
          (Ada_Node   => Ada_Node,
           Domain     => Domain,
           Name       => Name,
           Args       =>
             (1 =>
                Insert_Simple_Conversion
                  (Ada_Node => Ada_Node,
                   Domain   => Domain,
                   Expr     => Left,
                   To       => Base),
              2 =>
                Insert_Simple_Conversion
                  (Ada_Node => Ada_Node,
                   Domain   => Domain,
                   Expr     => Right,
                   To       => Base)),
           Check      => Domain = EW_Prog,
           Reason     => VC_Division_Check,
           Check_Info =>
             New_Check_Info (Divisor => Get_Ada_Node (+Right)),
           Typ        => Base);
   end;

function New_Operator_Call
  (Ada_Node   : Node_Id;
   Name       : W_Identifier_Id;
   Fix_Name   : Boolean := False;
   Args       : W_Expr_Array;
   Reason     : VC_Kind;
   Check      : Boolean;
   Domain     : EW_Domain;
   Typ        : W_Type_Id;
   Check_Info : Check_Info_Type := New_Check_Info) return W_Expr_Id
is
   Name_Spec : constant W_Identifier_Id :=
     (if Check and not Fix_Name then To_Program_Space (Name) else Name);
   Call      : constant W_Expr_Id :=
     New_Call
       (Ada_Node => Ada_Node,
        Name     => Name_Spec,
        Args     => Args,
        Domain   => Domain,
        Typ      => Typ);
begin
   if Check then
      return
        New_VC_Expr
          (Ada_Node   => Ada_Node,
           Reason     => Reason,
           Expr       => Call,
           Check_Info => Check_Info,
           Domain     => Domain);
   else
      return Call;
   end if;
end New_Operator_Call;

   elsif Nkind (N) in N_Unary_Op then
      return;

   --  Otherwise we will set the flag

   else
      null;
   end if;

--  Discrete case

else
   --  Nothing to do for Rem/Mod/Plus (overflow not possible, the check
   --  for zero-divide is a divide check, not an overflow check).

   if Nkind (N) in N_Op_Rem | N_Op_Mod | N_Op_Plus then
      return;
   end if;
end if;

